            <div class="forex-risk-metrics"><div><span>Best day</span><strong class="gain">{risk.best ? `${risk.best.returnPercent.toFixed(2)}%` : '—'}</strong><small>{risk.best ? dateLabel(risk.best.date) : 'Need 2 valuations'}</small></div><div><span>Worst day</span><strong class="loss">{risk.worst ? `${risk.worst.returnPercent.toFixed(2)}%` : '—'}</strong><small>{risk.worst ? dateLabel(risk.worst.date) : 'Need 2 valuations'}</small></div><div><span>Maximum drawdown</span><strong class="loss">{risk.points.length > 1 ? `${risk.maxDrawdown.toFixed(2)}%` : '—'}</strong><small>Peak to trough</small></div></div>
            {#if risk.points.length > 1}{@const plot = chartModel(risk.points, ['nav'], risk.currency, 'index')}<svg class="analysis-line-chart forex-nav-chart" viewBox="0 0 680 258" role="img" aria-label={`${risk.name} flow-adjusted growth index over time`}><text class="chart-axis-title" transform="translate(15 112) rotate(-90)">Growth index (start = 1.00)</text>{#each plot.yTicks as tick}<line x1={plot.left} y1={tick.y} x2={plot.right} y2={tick.y} class="chart-gridline"/><text x={plot.left - 9} y={tick.y + 3} text-anchor="end" class="chart-tick-label">{tick.label}</text>{/each}<line x1={plot.left} y1={plot.top} x2={plot.left} y2={plot.bottom} class="chart-axis"/><line x1={plot.left} y1={plot.bottom} x2={plot.right} y2={plot.bottom} class="chart-axis"/><polyline points={plot.paths.nav} class="chart-value-line"/>{#each plot.xTicks as tick}<line x1={tick.x} y1={plot.bottom} x2={tick.x} y2={plot.bottom + 4} class="chart-axis"/><text x={tick.x} y="224" text-anchor="middle" class="chart-tick-label">{tick.label}</text>{/each}<text x={(plot.left + plot.right) / 2} y="249" text-anchor="middle" class="chart-axis-title">Date</text></svg><div class="analysis-chart-legend"><span><i class="legend-value"></i>Flow-adjusted growth index</span><span>Index starts at 1.00 on the first valuation.</span></div>{/if}
            <h4>Daily flow-adjusted changes</h4><div class="analysis-table-wrap"><table class="analysis-table compact-analysis-table"><thead><tr><th>Date</th><th>Closing equity</th><th>Net-of-flow change</th><th>Daily return</th></tr></thead><tbody>{#each [...risk.points].reverse().slice(0, 20) as point}<tr><td>{dateLabel(point.date)}</td><td>{money(point.value, risk.currency)}</td><td class={changeClass(point.change)}>{point.change === 0 ? money(0, risk.currency) : money(point.change, risk.currency)}</td><td class={changeClass(point.returnPercent)}>{point.returnPercent === null ? '—' : `${point.returnPercent.toFixed(2)}%`}</td></tr>{:else}<tr><td colspan="4" class="analysis-table-empty">Record daily closing equity to build forex performance.</td></tr>{/each}</tbody></table></div>
          </article>{:else}<div class="analysis-panel analysis-empty-chart">No forex accounts yet. Add a forex account and record daily closing equity to calculate flow-adjusted performance and drawdown.</div>{/each}</div>
      </section>
      <footer class="dashboard-footer"><span>Investment data is based on your recorded trades, prices, transfers, and valuations.</span><span>USD and ZiG are not converted or combined.</span></footer>
    </div>
  </main>
